from pathlib import Path

home = Path('/home/ubuntu/tinkerbell-dc-prototype/client/src/pages/Home.tsx')
s = home.read_text()
needle = 'const recoverExpiredCoupons = () => {'
if needle not in s:
    raise SystemExit('recoverExpiredCoupons not found')
effect = '''useEffect(() => { const handleBulkVisit = (event: Event) => { const auth = (event as CustomEvent<MeetingBulkVisitAuth>).detail; if (!auth?.store) return; const matching = issuedCoupons.filter((record) => record.coupon.store === auth.store); if (!matching.length) return; const usedAt = auth.verifiedAt || new Date().toLocaleString("ko-KR", { dateStyle: "medium", timeStyle: "short" }); setIssuedCoupons((current) => current.filter((record) => record.coupon.store !== auth.store)); setReturnedCoupons((current) => [...matching.map((record) => ({ ...record, status: "USED" as CouponStatus, usedAt, bulkVisitVerified: true })), ...current]); setCouponWalletStatusRequest((value) => value + 1); showHeaderToast(`${auth.memberCount}명 참석자의 ${auth.store} 쿠폰이 사용 완료 처리되었습니다.`); }; window.addEventListener("dangam:meeting-bulk-visit", handleBulkVisit); return () => window.removeEventListener("dangam:meeting-bulk-visit", handleBulkVisit); }, [issuedCoupons]); '''
s = s.replace(needle, effect + needle, 1)
home.write_text(s)

css = Path('/home/ubuntu/tinkerbell-dc-prototype/client/src/index.css')
with css.open('a') as f:
    f.write('''\n\n/* Group gathering host bulk PIN check-in */\n.meeting-bulk-visit-panel { margin: 14px 0; padding: 14px; border: 1px solid #fed7aa; border-radius: 18px; background: #fff7ed; display: grid; gap: 10px; }\n.meeting-bulk-visit-panel.verified { border-color: #a7f3d0; background: #ecfdf5; }\n.meeting-bulk-visit-panel > div { display: grid; gap: 4px; }\n.meeting-bulk-visit-panel strong { font-size: 16px; font-weight: 800; color: #111827; line-height: 1.35; }\n.meeting-bulk-visit-panel span, .meeting-bulk-visit-panel small { font-size: 14px; font-weight: 600; color: #4b5563; line-height: 1.45; }\n.meeting-bulk-visit-panel button { min-height: 46px; border: 0; border-radius: 12px; padding: 0 12px; background: #111827; color: #fff; font-size: 16px; font-weight: 800; cursor: pointer; }\n.meeting-bulk-visit-panel button:disabled { background: #d1d5db; color: #6b7280; cursor: not-allowed; }\n.meeting-bulk-pin-overlay { z-index: 90; }\n.meeting-bulk-pin-sheet { width: min(94vw, 420px); max-height: 90vh; overflow: hidden; border-radius: 24px; background: #fff; padding: 24px 18px 20px; position: relative; box-shadow: 0 24px 70px rgba(15,23,42,.25); }\n.meeting-bulk-pin-sheet > .close-btn { position: absolute; top: 12px; right: 12px; }\n.meeting-bulk-pin-sheet h2 { margin: 6px 0 10px; font-size: 22px; font-weight: 900; line-height: 1.3; }\n.meeting-bulk-copy { margin: 0 0 12px; font-size: 16px; font-weight: 600; line-height: 1.5; color: #4b5563; }\n.meeting-bulk-target, .meeting-bulk-receipt { display: grid; gap: 5px; padding: 12px; border-radius: 14px; background: #f9fafb; border: 1px solid #e5e7eb; }\n.meeting-bulk-target strong { font-size: 17px; font-weight: 900; color: #111827; }\n.meeting-bulk-target span { font-size: 14px; font-weight: 600; color: #6b7280; }\n.meeting-bulk-pin-sheet .merchant-pin-dots { margin: 18px 0 12px; }\n.meeting-bulk-pin-sheet .merchant-keypad { gap: 8px; }\n.meeting-bulk-pin-sheet .merchant-keypad button { min-height: 46px; font-size: 16px; font-weight: 800; }\n.meeting-bulk-pin-sheet .merchant-test-pin { display: block; margin-top: 10px; text-align: center; font-size: 13px; color: #6b7280; }\n.meeting-bulk-success { display: grid; gap: 10px; text-align: center; padding-top: 12px; }\n.meeting-bulk-success .merchant-success-icon { margin: 0 auto; }\n.meeting-bulk-success h2 { margin-bottom: 0; }\n.meeting-bulk-success > p:not(.eyebrow) { margin: 0; font-size: 16px; font-weight: 600; line-height: 1.45; color: #4b5563; }\n.meeting-bulk-receipt { grid-template-columns: 1fr 1.4fr; text-align: left; }\n.meeting-bulk-receipt span { font-size: 13px; color: #6b7280; }\n.meeting-bulk-receipt b { font-size: 14px; color: #111827; overflow-wrap: anywhere; }\n''')
